(()=>{
  const ops={contactId:null,forwardMessageId:null,forwardInternalId:null,forwardAttendanceId:null,supervisionUserId:null,supervisionAttendanceId:null,contacts:[]};
  const contactsBox=$('#internal-contacts'),messagesBox=$('#internal-messages'),composer=$('#internal-composer'),threadTitle=$('#internal-thread-title');
  const presenceOrigin=APP_MODE?(/iPhone|iPad|iPod/i.test(navigator.userAgent)?'IOS':'ANDROID'):'WEB';
  const imageUrl=message=>`/api/admin/chat-interno-anexo?mensagemId=${encodeURIComponent(message.id)}`;
  const scrollInternal=()=>{const followLatest=()=>{messagesBox.scrollTop=messagesBox.scrollHeight;messagesBox.scrollTo({top:messagesBox.scrollHeight,left:0,behavior:'auto'})};requestAnimationFrame(()=>{followLatest();requestAnimationFrame(followLatest)});setTimeout(followLatest,80)};

  window.jllOperationsHeartbeat=()=>{if(state.user)api('/api/admin/presenca',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({origem:presenceOrigin})}).catch(()=>{})};

  function updateUnread(contacts){const total=(contacts||[]).reduce((sum,item)=>sum+Number(item.nao_lidas||0),0);['#internal-unread','#app-internal-unread'].forEach(selector=>{const badge=$(selector);badge.textContent=total;badge.hidden=!total})}
  function renderContacts(contacts){ops.contacts=contacts||[];updateUnread(ops.contacts);contactsBox.innerHTML=ops.contacts.map(contact=>`<button type="button" class="internal-contact ${String(contact.id)===ops.contactId?'active':''}" data-contact-id="${escapeHtml(contact.id)}"><span class="presence-dot ${contact.online?'online':'offline'}"></span><span><strong>${escapeHtml(contact.nome_exibicao)}</strong><small>${contact.online?'On-line':contact.ultima_atividade_em?`Visto em ${formatDate(contact.ultima_atividade_em)}`:'Off-line'}</small><em>${escapeHtml(contact.ultima_mensagem||'Iniciar conversa')}</em></span>${Number(contact.nao_lidas||0)?`<b>${contact.nao_lidas}</b>`:''}</button>`).join('')||'<p class="empty">Nenhum outro usuário ativo.</p>'}
  function renderInternalMessages(messages){messagesBox.innerHTML=(messages||[]).map(message=>{const mine=String(message.remetente_id)===String(state.user.id),attachment=message.anexo_id?`<button type="button" class="internal-image" data-image-url="${imageUrl(message)}"><img src="${imageUrl(message)}" alt="Imagem da conversa interna" loading="lazy"></button>`:'',origin=message.numero_atendimento?`<small class="forward-origin">Atendimento #${escapeHtml(message.numero_atendimento)}</small>`:'';return `<article class="internal-message ${mine?'mine':''}" data-message-id="${escapeHtml(message.id)}">${origin}${attachment}<span>${escapeHtml(message.texto||'').replace(/\r?\n/g,'<br>')}</span><div class="message-meta"><small>${formatDate(message.criado_em)}</small><button type="button" class="forward-internal" data-forward-internal="${escapeHtml(message.id)}">Encaminhar</button></div></article>`}).join('')||'<p class="empty">Nenhuma mensagem. Escreva para iniciar.</p>';scrollInternal();messagesBox.querySelectorAll('img').forEach(image=>image.addEventListener('load',scrollInternal,{once:true}))}
  async function loadInternal(contactId=ops.contactId,{quiet=false}={}){try{const query=contactId?`?contatoId=${encodeURIComponent(contactId)}`:'';const data=await api(`/api/admin/chat-interno${query}`);renderContacts(data.contatos||[]);if(contactId&&data.contato){ops.contactId=String(contactId);threadTitle.textContent=data.contato.nome_exibicao;composer.hidden=false;$('.internal-chat-layout').classList.add('thread-open');renderInternalMessages(data.mensagens||[]);renderContacts(data.contatos||[])}}catch(error){if(!quiet)showError(error)}}
  async function sendInternal(payload){if(!ops.contactId)return;await api('/api/admin/chat-interno',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({contatoId:ops.contactId,...payload})});ops.forwardMessageId=null;ops.forwardInternalId=null;ops.forwardAttendanceId=null;await loadInternal(ops.contactId)}

  contactsBox.addEventListener('click',async event=>{const button=event.target.closest('[data-contact-id]');if(!button)return;ops.contactId=button.dataset.contactId;if(ops.forwardMessageId){await sendInternal({mensagemAtendimentoId:ops.forwardMessageId});return}if(ops.forwardInternalId){await sendInternal({mensagemInternaId:ops.forwardInternalId});return}await loadInternal(ops.contactId)});
  composer.addEventListener('submit',async event=>{event.preventDefault();const input=event.currentTarget.elements.texto,text=input.value.trim();if(!text)return;const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{input.value='';await sendInternal({texto:text})}catch(error){input.value=text;showError(error)}finally{button.disabled=false;input.focus()}});
  $('#internal-attach').addEventListener('click',()=>window.jllOpenAttachmentPicker($('#internal-file')));
  $('#internal-back').addEventListener('click',()=>{$('.internal-chat-layout').classList.remove('thread-open');ops.contactId=null;threadTitle.textContent='Selecione um contato';composer.hidden=true});
  $('#internal-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file||!ops.contactId)return;try{if(file.size>4*1024*1024)throw new Error('A imagem deve ter no máximo 4 MB.');await sendInternal({fileName:file.name,mimeType:file.type,data:await fileToBase64(file)})}catch(error){showError(error)}finally{event.target.value=''}});
  messagesBox.addEventListener('click',event=>{const image=event.target.closest('[data-image-url]'),forward=event.target.closest('[data-forward-internal]');if(image){openMediaViewer(image.dataset.imageUrl,'Imagem da conversa interna');return}if(forward){ops.forwardInternalId=forward.dataset.forwardInternal;ops.forwardMessageId=null;$('.internal-chat-layout').classList.remove('thread-open');ops.contactId=null;threadTitle.textContent='Selecione o destinatário';composer.hidden=true}});
  document.addEventListener('click',event=>{const button=event.target.closest('[data-forward-message]');if(!button)return;ops.forwardMessageId=button.dataset.forwardMessage;ops.forwardInternalId=null;ops.forwardAttendanceId=button.dataset.forwardAttendance;switchView('internal-chat');$('.internal-chat-layout').classList.remove('thread-open');ops.contactId=null;composer.hidden=true;threadTitle.textContent='Selecione o destinatário';messagesBox.innerHTML='<p class="forward-guidance">Selecione um contato para encaminhar esta mensagem ou imagem.</p>'});

  function supervisionUserCard(user){return `<button type="button" class="supervision-user" data-supervision-user="${escapeHtml(user.id)}"><span class="presence-dot ${user.online?'online':'offline'}"></span><span><strong>${escapeHtml(user.nome_exibicao)}</strong><small>${escapeHtml(user.perfil)} · ${user.atendimentos_ativos} atendimento(s)</small></span></button>`}
  async function loadSupervision({quiet=false}={}){if(APP_MODE||!['ADMINISTRADOR','GESTOR'].includes(state.user?.perfil))return;try{const data=await api('/api/admin/supervisao'),online=(data.usuarios||[]).filter(item=>item.online),offline=(data.usuarios||[]).filter(item=>!item.online);$('#supervision-online').innerHTML=online.map(supervisionUserCard).join('')||'<p class="empty">Nenhum usuário on-line.</p>';$('#supervision-offline').innerHTML=offline.map(supervisionUserCard).join('')||'<p class="empty">Nenhum usuário off-line.</p>'}catch(error){if(!quiet)showError(error)}}
  async function openSupervisionUser(id){ops.supervisionUserId=id;const data=await api(`/api/admin/supervisao?usuarioId=${encodeURIComponent(id)}`);$('#supervision-attendances').innerHTML=(data.atendimentos||[]).map(item=>`<button type="button" data-supervision-attendance="${escapeHtml(item.id)}"><strong>#${item.numero_atendimento} · ${escapeHtml(item.nome_cliente)}</strong><small>${escapeHtml(item.status)} · ${formatDate(item.atualizado_em)}</small></button>`).join('')||'<p class="empty">Este usuário não possui atendimentos ativos.</p>'}
  async function openSupervisionAttendance(id){ops.supervisionAttendanceId=id;const data=await api(`/api/admin/supervisao?atendimentoId=${encodeURIComponent(id)}`),a=data.atendimento,box=$('#supervision-conversation');box.innerHTML=`<header><h3>#${a.numero_atendimento} · ${escapeHtml(a.nome_cliente)}</h3><p>Responsável: ${escapeHtml(a.atendente_nome||'Não atribuído')}</p></header><div class="supervision-messages">${(data.mensagens||[]).map(message=>renderConversationMessage(message,id)).join('')}</div><form id="supervision-composer"><input name="texto" placeholder="Responder como administrador" required><button>Enviar</button></form>`;const messages=box.querySelector('.supervision-messages');requestAnimationFrame(()=>messages.scrollTop=messages.scrollHeight);box.querySelector('#supervision-composer').addEventListener('submit',async event=>{event.preventDefault();const input=event.currentTarget.elements.texto,button=event.currentTarget.querySelector('button'),text=input.value.trim();if(!text)return;button.disabled=true;try{await api('/api/admin/supervisao',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({atendimentoId:id,texto:text})});await openSupervisionAttendance(id)}catch(error){showError(error)}finally{button.disabled=false}})}
  $('#supervision-view').addEventListener('click',event=>{const userButton=event.target.closest('[data-supervision-user]'),attendanceButton=event.target.closest('[data-supervision-attendance]');if(userButton)openSupervisionUser(userButton.dataset.supervisionUser).catch(showError);if(attendanceButton)openSupervisionAttendance(attendanceButton.dataset.supervisionAttendance).catch(showError)});

  window.jllOpenOperationalView=view=>{if(view==='internal-chat')loadInternal();if(view==='supervision')loadSupervision()};
  window.jllRefreshOperationalView=view=>{if(view==='internal-chat')loadInternal(ops.contactId,{quiet:true});if(view==='supervision'){loadSupervision({quiet:true});if(ops.supervisionAttendanceId)openSupervisionAttendance(ops.supervisionAttendanceId).catch(()=>{})}};
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user){window.jllOperationsHeartbeat();window.jllRefreshOperationalView(state.currentView)}});
  const previousBackHandler=window.jllHandleAndroidBack;window.jllHandleAndroidBack=()=>{if(state.currentView==='internal-chat'&&$('.internal-chat-layout').classList.contains('thread-open')){$('.internal-chat-layout').classList.remove('thread-open');ops.contactId=null;threadTitle.textContent='Selecione um contato';composer.hidden=true;return true}return previousBackHandler?.()||false};
})();
